package com.retail.inventory.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.retail.inventory.dto.request.*;import com.retail.inventory.dto.response.*;import com.retail.inventory.entity.enums.*;import com.retail.inventory.exception.GlobalExceptionHandler;import com.retail.inventory.service.OrderService;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.data.jpa.mapping.JpaMetamodelMappingContext;import org.springframework.http.*;import org.springframework.test.web.servlet.MockMvc;import java.math.*;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(OrderController.class)@Import(GlobalExceptionHandler.class)class OrderControllerTest{@Autowired MockMvc mvc;@Autowired ObjectMapper json;@MockBean OrderService service;@MockBean(name="jpaMappingContext")JpaMetamodelMappingContext context;
 @Test void coversEndpointsAndValidation()throws Exception{OrderResponse r=OrderResponse.builder().id(1L).orderNumber("SO-1").status(OrderStatus.DRAFT).items(List.of()).build();when(service.findById(1L)).thenReturn(r);when(service.create(any())).thenReturn(r);when(service.updateStatus(anyLong(),any())).thenReturn(r);when(service.cancel(1L)).thenReturn(r);when(service.items(1L)).thenReturn(List.of());when(service.findAll(any(),any(),any(),any(),any())).thenReturn(new org.springframework.data.domain.PageImpl<>(List.of(r)));var req=CreateOrderRequest.builder().orderType(OrderType.SALES_ORDER).warehouseId(1L).items(List.of(OrderItemRequest.builder().productId(1L).quantity(1).unitPrice(BigDecimal.ONE).build())).build();mvc.perform(get("/v1/orders")).andExpect(status().isOk());mvc.perform(get("/v1/orders/1")).andExpect(status().isOk());mvc.perform(post("/v1/orders").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(req))).andExpect(status().isCreated());mvc.perform(put("/v1/orders/1/status").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"PENDING\"}")).andExpect(status().isOk());mvc.perform(post("/v1/orders/1/cancel")).andExpect(status().isOk());mvc.perform(get("/v1/orders/1/items")).andExpect(status().isOk());mvc.perform(post("/v1/orders").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest());}}
